class Effect {
  static CONFIG = {
    trail_length: {
      default: 60,
      type: 'range', min: 5, max: 200, step: 1,
      label: '轨迹长度',
      description: '轨迹点越多拖尾越长',
    },
    start_color: {
      default: '#00aaff',
      type: 'color',
      label: '起始颜色',
      description: '轨迹起始颜色（蓝色系）',
    },
    end_color: {
      default: '#8a2be2',
      type: 'color',
      label: '结束颜色',
      description: '轨迹结束颜色（紫色系）',
    },
    speed_threshold: {
      default: 6,
      type: 'range', min: 0, max: 20, step: 0.5,
      label: '爆发阈值',
      description: '超过该速度触发粒子爆发',
    },
    particle_count: {
      default: 60,
      type: 'range', min: 1, max: 200, step: 1,
      label: '爆粒数量',
      description: '粒子爆发数量',
    },
    particle_life: {
      default: 90,
      type: 'range', min: 10, max: 300, step: 1,
      label: '粒子寿命',
      description: '粒子存在帧数',
    },
  };

  constructor() {
    this.lastFrame = -1;
    this.prevPos = {};
    this.trails = {};
    this.particles = [];
  }

  display(sketch, frameData, params) {
    // 跳帧检测：跳帧后重置所有时序状态
    if (this.lastFrame >= 0 && frameData.currentFrame - this.lastFrame > 1) {
      this.trails = {};
      this.particles = [];
      this.prevPos = {};
    }
    const frameDelta = Math.max(1, frameData.currentFrame - this.lastFrame);
    this.lastFrame = frameData.currentFrame;

    const startColor = sketch.color(params.start_color);
    const endColor = sketch.color(params.end_color);

    ['right_wrist', 'left_wrist'].forEach((joint) => {
      const pos = frameData.joints?.[joint];
      if (!pos) return;

      const arr = this.trails[joint] || (this.trails[joint] = []);
      arr.push({ x: pos.x, y: pos.y });
      if (arr.length > params.trail_length) arr.shift();

      const last = this.prevPos[joint];
      let speed = 0;
      if (last) {
        const dx = pos.x - last.x;
        const dy = pos.y - last.y;
        speed = Math.sqrt(dx * dx + dy * dy) / frameDelta;
      }
      this.prevPos[joint] = { x: pos.x, y: pos.y };

      // 轨迹：蓝 → 紫渐变
      if (arr.length > 1) {
        sketch.push();
        sketch.noFill();
        for (let i = 0; i < arr.length - 1; i++) {
          const t = i / Math.max(1, arr.length - 2);
          sketch.stroke(sketch.lerpColor(startColor, endColor, t));
          sketch.strokeWeight(speed > params.speed_threshold ? 1.8 : 2.5);
          sketch.line(arr[i].x, arr[i].y, arr[i + 1].x, arr[i + 1].y);
        }
        sketch.pop();
      }

      // 快速移动时粒子爆发
      if (speed > params.speed_threshold) {
        for (let i = 0; i < params.particle_count; i++) {
          const ang = sketch.random(0, Math.PI * 2);
          const mag = sketch.random(0.5, 2.5);
          this.particles.push({
            x: pos.x,
            y: pos.y,
            vx: Math.cos(ang) * mag,
            vy: Math.sin(ang) * mag,
            bornFrame: frameData.currentFrame,
          });
        }
      }
    });

    // 粒子更新与绘制（生命周期基于帧号）
    const alive = [];
    for (const p of this.particles) {
      const age = frameData.currentFrame - p.bornFrame;
      if (age > params.particle_life) continue;
      p.x += p.vx;
      p.y += p.vy;
      p.vx *= 0.98;
      p.vy *= 0.98;
      const alpha = 1 - age / params.particle_life;
      sketch.push();
      sketch.noStroke();
      sketch.fill(255, 240, 180, Math.floor(180 * alpha));
      sketch.ellipse(p.x, p.y, 2 + 3 * alpha, 2 + 3 * alpha);
      sketch.pop();
      alive.push(p);
    }
    this.particles = alive;
  }
}
